import numpy as np
from treehfd import XGBTreeHFD


def _pair_importance(model, p):
    df = model.get_booster().trees_to_dataframe()
    names = model.get_booster().feature_names
    idx = {n: i for i, n in enumerate(names)} if names else {}

    def fid(f):
        if f in idx:
            return idx[f]
        return int(str(f).lstrip("f"))

    imp = {}
    for _, t in df.groupby("Tree"):
        rows = {r.ID: r for r in t.itertuples()}
        root = t.iloc[0]["ID"]
        stack = [(root, ())]
        while stack:
            nid, anc = stack.pop()
            r = rows[nid]
            if r.Feature == "Leaf":
                continue
            f = fid(r.Feature)
            for a in set(anc):
                if a != f:
                    key = (min(a, f), max(a, f))
                    imp[key] = imp.get(key, 0.0) + float(r.Gain)
            na = anc + (f,)
            stack.append((r.Yes, na))
            stack.append((r.No, na))
    return imp


def decompose(model, X_train, X_test):
    p = X_train.shape[1]
    K = 2 * p
    try:
        imp = _pair_importance(model, p)
    except Exception:
        imp = {}
    ranked = sorted(imp.items(), key=lambda kv: -kv[1])
    pairs = [k for k, _ in ranked[:K]]
    if not pairs:
        pairs = [(a, b) for a in range(p) for b in range(a + 1, p)][:K]
    il = np.array(pairs, dtype=int).reshape(-1, 2)

    hfd = XGBTreeHFD(model)
    try:
        hfd.fit(X_train, interaction_order=2, interaction_list=il,
                verbose=False)
    except TypeError:
        hfd.fit(X_train, interaction_order=2, verbose=False)
    y_main, y_order2 = hfd.predict(X_test, verbose=False)
    comps = {(j,): y_main[:, j] for j in range(y_main.shape[1])}
    for k, (a, b) in enumerate(hfd.interaction_list):
        a, b = int(a), int(b)
        comps[(min(a, b), max(a, b))] = y_order2[:, k]
    return float(hfd.eta0), comps


def _winsorise_components(components, lower=0.01, upper=0.99):
    """Clip every component to its own quantile range (a step the paper does not describe)."""
    clipped = {}
    for key, values in components.items():
        lo, hi = np.quantile(values, [lower, upper])
        clipped[key] = np.clip(values, lo, hi)
    return clipped
